<!-- jhjm-guess-what Puzzle | Generated by EterIll's CCXC Problem Template X -->
<template>


    <div class="container p-5 border border-black mb-3">
        <div v-if="globalError" class="alert alert-danger">
            {{ globalError }}
        </div>
        <form @submit.prevent="submit" autocomplete="off">
            <div class="guesser">
                <input id="guess" v-model="guessWord" type="text" placeholder="请输入二字词语" :disabled="isSubmitting">
                <button id="submit" class="btn galatic-btn" type="submit" :disabled="isSubmitting">
                    确认
                </button>
            </div>
        </form>
        <div>
            <div class="row">
                <div class="col-2 text-center"></div>
                <div class="col-10 align-self-center text-center">
                    <span id="word" v-if="lastSubmit">“{{ lastSubmit }}”</span>相关度
                </div>
            </div>
            <table style="width: 100%;">
                <tbody style="width: 100%;">
                    <tr v-for="(item, index) in relevanceItems" :key="index">
                        <td style="width: 2.4rem">{{ item.label }}</td>
                        <td>
                            <div class="progress-stacked" :id="'result-' + index" style="width: 100%;">
                                <div v-for="n in (item.value + 1)" :key="n" class="progress qt-progress">
                                    <div class="progress-bar" :class="`qt-p${n - 1}`"></div>
                                </div>
                            </div>
                        </td>
                    </tr>
                </tbody>
            </table>
        </div>
    </div>


</template>
<style>

.guesser{
    width: 100%;
    display: flex;
    flex-direction: row;
}
#guess {
    width: 60%;
    margin-left: 10%;
    margin-right: 10%;
}

#submit {
    width: 20%;
}

.qt-progress {
    width: 20%;
    border-right: 2px solid white;
}

.empty-progress {
    width: 0%;
}

.qt-p0 {
    background-color: #999;
}

.qt-p1 {
    background-color: #F5B7B1;
}

.qt-p2 {
    background-color: #F9E79F;
}

.qt-p3 {
    background-color: #D4EFDF;
}

.qt-p4 {
    background-color: #0F0;
}

.galatic-btn {
    background: rgb(0, 85, 170);
    color: #fff;
}

.galatic-btn:hover,
.galatic-btn:focus {
    color: #fff;
    background: #2af;
}

.progress-stacked {
    display: flex;
    height: 1rem;
    border-radius: .5rem;
    overflow: hidden;
}

.qt-progress {
    height: 1.5rem;
    overflow: hidden;
}

.progress-bar {
    width: 100%;
    height: 100%;
}


</style>


